"끝에 가까워질수록 곁이 조용해졌다":"ยิ่งใกล้ถึงตอนท้าย รอบกายก็ยิ่งเงียบลง",
"날마다 걷는다":"เดินทุกวัน",
"낡은 벽지를 걷어 내고 방 하나를 서재로 바꾸니 같은 집이 낯설게 환했다":"ลอกวอลเปเปอร์เก่าออกแล้วเปลี่ยนห้องหนึ่งเป็นห้องหนังสือ บ้านหลังเดิมก็สว่างจนดูแปลกตา",
