"남길 만한 얘기가 못 된다며 손을 내젓고 괜히 창밖만 오래 보았다":"โบกมือบอกว่าไม่ใช่เรื่องที่ควรเก็บไว้ แล้วได้แต่มองออกไปนอกหน้าต่างอยู่นาน",
"남은 사람들을 불러 상 하나에 둘러앉아 옛날 얘기로 해가 지는 줄 몰랐다":"เรียกคนที่เหลืออยู่มานั่งล้อมโต๊ะเดียวกัน เล่าเรื่องเก่าๆ จนไม่รู้ตัวว่าพระอาทิตย์ตกแล้ว",
"남은 일할 날을 세어 보니 노후가 걱정된다":"นับวันทำงานที่เหลือแล้วก็เริ่มกังวลเรื่องวัยชรา",
