"녹음기를 켜 놓고 어릴 적 살던 골목 이야기부터 밤이 깊도록 풀어놓았다":"เปิดเครื่องอัดเสียงแล้วเล่าเรื่องตั้งแต่ซอยที่เคยอยู่สมัยเด็กไปจนดึกดื่น",
