"더 지켜본다":"รอดูอีกสักพัก",
"동네 놀이터에서 낯선 아이에게 장난감을 내밀던 그날처럼 나눠 준 것이 돌아와 이웃이 먼저 문을 열어 주었다":"เหมือนวันที่ยื่นของเล่นให้เด็กแปลกหน้าที่สนามเด็กเล่นในละแวกบ้าน สิ่งที่แบ่งปันไปก็ย้อนกลับมา เพื่อนบ้านเป็นฝ่ายเปิดประตูให้ก่อน",
