"뚜껑 위의 먼지만 소매로 쓸어 내고 상자를 원래 자리에 도로 밀어 넣었다":"ใช้แขนเสื้อปัดฝุ่นบนฝาออกเท่านั้น แล้วดันกล่องกลับเข้าที่เดิม",
