"멀리 나가 본다":"ออกไปไกลๆ",
"모임 사람들이 힘든 시기마다 말없이 밥을 챙겨 주던 일이 쌓여 어느덧 가장 오래된 이웃이 되어 있었다":"เรื่องที่คนในกลุ่มคอยดูแลเรื่องข้าวปลาอย่างเงียบๆ ในทุกช่วงที่ลำบากสะสมมาเรื่อยๆ จนไม่ทันรู้ตัวก็กลายเป็นเพื่อนบ้านที่อยู่ด้วยกันมานานที่สุด",
"몸이 예전 같지 않다. 계단 앞에서 숨을 고른다":"ร่างกายไม่เหมือนเมื่อก่อนแล้ว ยืนหยุดหายใจอยู่หน้าบันได",
"무리하지 않기로 하고 낮잠 한 번에 차 한 잔으로 오후를 채웠다":"ตัดสินใจไม่ฝืนตัวเอง แล้วใช้บ่ายนั้นไปกับการงีบหนึ่งครั้งและชาหนึ่งถ้วย",
"문을 두드려 본다":"ลองเคาะประตู",
"문을 열고 들어가 쓰러진 이웃을 일으켜 앉히고 구급차를 불러 같이 기다렸다":"เปิดประตูเข้าไป ประคองเพื่อนบ้านที่ล้มอยู่ให้ลุกขึ้นนั่ง เรียกรถพยาบาล แล้วรอด้วยกัน",
