"물 길러 가는 길을 두고 학교로 향하던 그날의 발걸음이 오늘의 내 책상까지 곧게 이어져 있었다":"ก้าวเดินในวันที่ละทางไปตักน้ำแล้วมุ่งไปโรงเรียน ทอดตรงมาจนถึงโต๊ะของฉันในวันนี้",
