"미뤄 둔 가족 여행을 끊고 돌아오는 기차에서 처음으로 노후 생각을 잊었다":"จองทริปครอบครัวที่เลื่อนมาตลอด แล้วบนรถไฟขากลับก็ลืมเรื่องวัยชราเป็นครั้งแรก",
"미리 나눠 준다":"แบ่งให้ล่วงหน้า",
"미역국 한 그릇에 가까운 사람 몇이 둘러앉은 소박한 밥상이 오히려 제일 따뜻했다":"โต๊ะอาหารเรียบง่ายที่มีแกงจืดสาหร่ายหนึ่งชามกับคนสนิทไม่กี่คนนั่งล้อมวง กลับอบอุ่นที่สุด",
"발표를 미루던 짝의 얼굴이 문득 떠올라, 오늘은 내가 먼저 하겠다며 자료를 들고 일어섰다":"ใบหน้าของคู่ที่เคยเลื่อนการนำเสนอผุดขึ้นมา ฉันจึงถือเอกสารลุกขึ้นพร้อมบอกว่าวันนี้ขอเป็นฝ่ายไปก่อนเอง",
"번갈아 물을 나르던 이웃 아이가 어른이 되어 찾아와 그때의 반쯤 찬 물동이를 웃으며 이야기했다":"เด็กข้างบ้านที่เคยผลัดกันขนน้ำมาหาตอนโตแล้ว แล้วหัวเราะเล่าถึงโอ่งน้ำที่เต็มแค่ครึ่งเดียวในตอนนั้น",
