"비워서 냈던 진로 상담지가 떠오르던 날 오래 미뤄 둔 질문을 노트 첫 장에 처음으로 적어 보았다":"วันที่นึกถึงใบปรึกษาเรื่องเส้นทางอนาคตที่เคยส่งเป็นกระดาษเปล่า ฉันเขียนคำถามที่เลื่อนมานานลงบนหน้าแรกของสมุดเป็นครั้งแรก",
"사람들을 부른다":"เรียกทุกคนมา",
