"멀리 떨어진 친척에게 전화를 걸어 요즘 읽는 책 이야기를 꺼냈더니 밤이 깊도록 통화가 이어졌다":"โทรหาญาติที่อยู่ไกล เล่าเรื่องหนังสือที่อ่านช่วงนี้ คุยโทรศัพท์กันจนดึก",
