"멀리 사는 조카에게 안부 전화를 걸어 요즘 식사는 어떠냐고 묻자 한참 어릴 적 이야기가 따라 나왔다":"โทรไปถามสารทุกข์สุขดิบหลานที่อยู่ไกล ถามว่าช่วงนี้กินข้าวเป็นยังไงบ้าง เรื่องสมัยเด็กก็ตามมาเป็นพรวน",
"멀리 이사 간 친구에게 짧게 안부 문자를 보냈더니 긴 답장이 와서 내내 휴대폰을 쥐고 웃었다":"ส่งข้อความทักทายสั้น ๆ ถึงเพื่อนที่ย้ายไปไกล ได้คำตอบยาว ๆ กลับมา เลยกำโทรศัพท์ยิ้มไปตลอด",
"며칠 뒤 우편함에 도착한 결과지를 열어 모든 수치가 정상 범위에 걸쳐 있는 걸 확인하고 한숨 돌렸다":"อีกไม่กี่วันเปิดใบผลตรวจที่มาถึงตู้ไปรษณีย์ เห็นว่าทุกค่าอยู่ในช่วงปกติก็โล่งใจ",
